 perror("socket");
 exit(1);
 } memset(&sock_in, 0, sizeof(sock_in));
 sock_in.sin_family = AF_INET;
 sock_in.sin_port = htons(atoi(port));
 sock_in.sin_addr.s_addr = INADDR_ANY;
 len = sizeof(sock_in); opt = 1;
 if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(int)) == -1) {
 perror("setsockopt");
 exit(1);
 } if (bind(fd, (struct sockaddr *)&sock_in, len) < 0) {
 perror("bind");
 exit(1);
 } if (listen(fd, 5) < 0) {
 perror("listen");
 exit(1);
 } printf("listening on port %d\n", atoi(port)); for (;;) {
 len = sizeof(sock_out);
 if ((a = accept(fd, (struct sockaddr *)&sock_out, &len)) < 0){
 perror("accept");
 exit(1);
 }
 printf("got a connection from %s\n", inet_ntoa(sock_out.sin_addr));
 fflush(stdout); write(a, bigbuf, sizeof(bigbuf));
 close(a);
 } return(1);}

